<#
  Fix-LaunchDateToSoon.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  What this changes:

  The order-blocking gate itself is UNTOUCHED - it still blocks placing an
  order for anyone except the allowlisted test email
  (src\app\send-package\step-3\page.jsx, LAUNCH_GATE_ALLOWED_EMAIL). This
  script only removes the fixed "August 15, 2026" date everywhere it
  appeared and replaces it with generic "launching soon" / "soon" wording:

    - src\components\ui\ShareButton.jsx: the native-share text.
    - src\app\layout.js: page title, meta description, Open Graph and
      Twitter card title/description/image alt text.
    - src\app\send-package\step-3\page.jsx: the "We're almost open!" gate
      modal a blocked person sees when trying to place an order.

  Note: this gate only exists in the send-package (customer) flow - there
  is no separate launch gate found anywhere in
  src\app\vendor\create-delivery\page.jsx or elsewhere in the app. If you
  meant a different/additional block specifically for vendors, let me know
  and I'll track that down separately.

  When you're ready to actually launch: change LAUNCH_GATE_ALLOWED_EMAIL's
  check in step-3\page.jsx (or remove the gate entirely) to let everyone
  through - that one flip is the "remove the block" step, kept separate on
  purpose so it only happens when you say so.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-launch-soon\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-LaunchDateToSoon.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-launch-soon"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying launch-date-to-soon fix:" -ForegroundColor Cyan

$b64_SHAREBUTTON = ""
Write-FileFromBase64 "src\components\ui\ShareButton.jsx" $b64_SHAREBUTTON

$b64_LAYOUT = ""
Write-FileFromBase64 "src\app\layout.js" $b64_LAYOUT

$b64_SENDSTEP3 = ""
Write-FileFromBase64 "src\app\send-package\step-3\page.jsx" $b64_SENDSTEP3

Write-Host "`nDone. Backups saved under .fix-backup-launch-soon\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
